  3	import com.zaxxer.hikari.HikariDataSource;
  4	
  5	public final class Main {
  6	    private Main() {}
  7	
  8	    public static void main(String[] args) throws Exception {
  9	        String url = require("DB_URL");
 10	        HikariDataSource ds = Db.connect(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 11	        Db.migrate(ds);
 12	        String port = System.getenv("PORT");
 13	        Api.create(new ReservationService(ds)).start(port == null || port.isBlank() ? 7070 : Integer.parseInt(port.trim()));
 14	    }
 15	
 16	    private static String require(String name) {
 17	        String v = System.getenv(name);
 18	        if (v == null || v.isBlank()) throw new IllegalStateException("Variável de ambiente " + name + " não definida");
 19	        return v;
 20	    }
 21	}
 22	package pousada;
 23	
 24	import com.fasterxml.jackson.core.JsonProcessingException;
 25	import com.fasterxml.jackson.databind.JsonNode;
 26	import com.fasterxml.jackson.databind.ObjectMapper;
 27	import io.javalin.Javalin;
 28	import io.javalin.http.Context;
 29	import pousada.plan.RatePlan;
 30	import pousada.plan.RatePlans;
 31	
 32	import java.math.BigDecimal;
 33	import java.time.LocalDate;
 34	import java.time.YearMonth;
 35	import java.time.format.DateTimeParseException;
 36	import java.util.LinkedHashMap;
 37	import java.util.List;
 38	import java.util.Map;
 39	
 40	public final class Api {
 41	    private static final ObjectMapper MAPPER = new ObjectMapper();
 42	
 43	    private final ReservationService service;
 44	
 45	    private Api(ReservationService service) {
 46	        this.service = service;
 47	    }
 48	
 49	    public static Javalin create(ReservationService service) {
 50	        Api api = new Api(service);
 51	        Javalin app = Javalin.create(cfg -> cfg.showJavalinBanner = false);
 52	
 53	        app.get("/rooms", api::rooms);
 54	        app.post("/reservations", api::create);
 55	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservationJson(service.get(id(ctx)))));
 56	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, reservationJson(service.confirm(id(ctx)))));
 57	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, reservationJson(service.cancel(id(ctx)))));
 58	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, reservationJson(service.checkIn(id(ctx)))));
 59	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, documentJson(service.checkOut(id(ctx)))));
 60	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, documentJson(service.document(id(ctx)))));
 61	        app.get("/messages", api::messages);
 62	        app.get("/reports/occupancy", ctx -> csv(ctx, service.occupancyCsv(
 63	                date(ctx.queryParam("date"), "date"))));
 64	        app.get("/reports/revenue", ctx -> csv(ctx, service.revenueCsv(month(ctx.queryParam("month")))));
 65	
 66	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status, e.code, e.getMessage()));
 67	        app.exception(Exception.class, (e, ctx) -> {
 68	            e.printStackTrace();
 69	            error(ctx, 500, "INTERNAL_ERROR", "Erro interno");
 70	        });
 71	        return app;
 72	    }
 73	
 74	    // ---------- handlers ----------
 75	
 76	    private void rooms(Context ctx) {
 77	        List<Map<String, Object>> out = service.rooms().stream().map(r -> {
 78	            Map<String, Object> m = new LinkedHashMap<>();
 79	            m.put("number", r.number());
 80	            m.put("type", r.type());
 81	            m.put("capacity", r.capacity());
 82	            m.put("nightlyRate", money(r.nightlyRate()));
 83	            return m;
 84	        }).toList();
 85	        json(ctx, 200, out);
 86	    }
 87	
 88	    private void messages(Context ctx) {
 89	        List<Map<String, Object>> out = service.messages().stream().map(m -> {
 90	            Map<String, Object> o = new LinkedHashMap<>();
 91	            o.put("id", m.id());
 92	            o.put("channel", m.channel());
 93	            o.put("to", m.to());
 94	            o.put("subject", m.subject());
 95	            o.put("body", m.body());
 96	            return o;
 97	        }).toList();
 98	        json(ctx, 200, out);
 99	    }
100	
101	    private void create(Context ctx) {
102	        JsonNode body;
103	        try {
104	            body = MAPPER.readTree(ctx.body());
105	        } catch (JsonProcessingException e) {
106	            throw ApiException.invalid("O corpo precisa ser um JSON válido");
107	        }
108	        if (body == null || !body.isObject()) throw ApiException.invalid("O corpo precisa ser um objeto JSON");
109	
110	        String name = text(body, "guestName");
111	        String email = text(body, "guestEmail");
112	        String cpf = text(body, "guestCpf");
113	        LocalDate checkIn = date(text(body, "checkIn"), "checkIn");
114	        LocalDate checkOut = date(text(body, "checkOut"), "checkOut");
115	        JsonNode roomNode = body.get("roomNumber");
116	        JsonNode guestsNode = body.get("guests");
117	        if (roomNode == null || !roomNode.isIntegralNumber() || !roomNode.canConvertToInt()) {
118	            throw ApiException.invalid("roomNumber é obrigatório e deve ser um número inteiro");
119	        }
120	        if (guestsNode == null || !guestsNode.isIntegralNumber() || !guestsNode.canConvertToInt()) {
121	            throw ApiException.invalid("guests é obrigatório e deve ser um número inteiro");
122	        }
123	        String planName = text(body, "ratePlan");
124	        RatePlan plan = RatePlans.find(planName)
125	                .orElseThrow(() -> ApiException.invalid("ratePlan desconhecido: " + planName));
126	        if (!checkOut.isAfter(checkIn)) throw ApiException.invalid("A saída precisa ser depois da entrada");
127	        int guests = guestsNode.intValue();
128	        if (guests < 1) throw ApiException.invalid("É preciso pelo menos um hóspede");
129	        JsonNode company = body.get("companyCode");
130	        String companyCode = company != null && company.isTextual() ? company.textValue() : null;
131	
132	        Reservation r = service.create(new ReservationService.NewReservation(
133	                roomNode.intValue(), name, email, cpf, checkIn, checkOut, guests, plan, companyCode));
134	        json(ctx, 201, reservationJson(r));
135	    }
136	
137	    // ---------- conversões ----------
138	
139	    private static Map<String, Object> reservationJson(Reservation r) {
140	        Map<String, Object> m = new LinkedHashMap<>();
141	        m.put("id", r.id());
142	        m.put("roomNumber", r.roomNumber());
143	        m.put("guestName", r.guestName());
144	        m.put("guestEmail", r.guestEmail());
145	        m.put("guestCpf", r.guestCpf());
146	        m.put("checkIn", r.checkIn().toString());
147	        m.put("checkOut", r.checkOut().toString());
148	        m.put("guests", r.guests());
149	        m.put("ratePlan", r.ratePlan());
150	        m.put("nights", r.nights());
151	        m.put("subtotal", money(r.subtotal()));
152	        m.put("discount", money(r.discount()));
153	        m.put("total", money(r.total()));
154	        m.put("status", r.status());
155	        m.put("amountPaid", money(r.amountPaid()));
156	        m.put("refund", r.refund() == null ? null : money(r.refund()));
157	        return m;
158	    }
159	
160	    private static Map<String, Object> documentJson(Reservation r) {
161	        Map<String, Object> m = new LinkedHashMap<>();
162	        m.put("title", "Comprovante de reserva");
163	        m.put("reservationId", r.id());
164	        m.put("guestName", r.guestName());
165	        m.put("guestCpf", r.guestCpf());
166	        m.put("roomNumber", r.roomNumber());
167	        m.put("roomType", r.roomType());
168	        m.put("checkIn", r.checkIn().toString());
169	        m.put("checkOut", r.checkOut().toString());
170	        m.put("nights", r.nights());
171	        m.put("subtotal", money(r.subtotal()));
172	        m.put("discount", money(r.discount()));
173	        m.put("total", money(r.total()));
174	        return m;
175	    }
176	
177	    private static BigDecimal money(BigDecimal v) {
178	        return Money.round(v);
179	    }
180	
181	    // ---------- utilitários ----------
182	
183	    private static long id(Context ctx) {
184	        String raw = ctx.pathParam("id");
185	        try {
186	            return Long.parseLong(raw);
187	        } catch (NumberFormatException e) {
188	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + raw + " não existe");
189	        }
190	    }
191	
192	    private static String text(JsonNode body, String field) {
193	        JsonNode n = body.get(field);
194	        if (n == null || !n.isTextual() || n.textValue().isBlank()) {
195	            throw ApiException.invalid(field + " é obrigatório");
196	        }
197	        return n.textValue();
198	    }
199	
200	    private static LocalDate date(String raw, String field) {
201	        if (raw == null) throw ApiException.invalid(field + " é obrigatório (formato 2027-07-10)");
202	        try {
203	            return LocalDate.parse(raw);
204	        } catch (DateTimeParseException e) {
205	            throw ApiException.invalid(field + " deve estar no formato 2027-07-10");
206	        }
207	    }
208	
209	    private static YearMonth month(String raw) {
210	        if (raw == null) throw ApiException.invalid("month é obrigatório (formato 2027-07)");
211	        try {
212	            return YearMonth.parse(raw);
213	        } catch (DateTimeParseException e) {
214	            throw ApiException.invalid("month deve estar no formato 2027-07");
215	        }
216	    }
217	
218	    private static void json(Context ctx, int status, Object body) {
219	        try {
220	            ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(body));
221	        } catch (JsonProcessingException e) {
222	            throw new IllegalStateException(e);
223	        }
224	    }
225	
226	    private static void csv(Context ctx, String body) {
227	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
228	    }
229	
230	    private static void error(Context ctx, int status, String code, String message) {
231	        Map<String, Object> m = new LinkedHashMap<>();
232	        m.put("error", code);
233	        m.put("message", message);
234	        json(ctx, status, m);
235	    }
236	}

