  1	package pousada;
  2	
  3	import pousada.plan.BookingContext;
  4	import pousada.plan.Quote;
  5	import pousada.plan.RatePlan;
  6	import pousada.plan.RatePlans;
  7	
  8	import javax.sql.DataSource;
  9	import java.math.BigDecimal;
 10	import java.sql.Connection;
 11	import java.sql.Date;
 12	import java.sql.PreparedStatement;
 13	import java.sql.ResultSet;
 14	import java.sql.SQLException;
 15	import java.sql.Statement;
 16	import java.sql.Types;
 17	import java.time.LocalDate;
 18	import java.util.ArrayList;
 19	import java.util.List;
 20	
 21	public class ReservationService {
 22	    public static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
 23	
 24	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 25	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan plan,
 26	                                 String companyCode) {}
 27	
 28	    public record Message(long id, String channel, String to, String subject, String body) {}
 29	
 30	    private interface Work<T> { T run(Connection c) throws SQLException; }
 31	
 32	    private static final String SELECT_RESERVATION = """
 33	            SELECT r.*, ro.type AS room_type FROM reservations r JOIN rooms ro ON ro.number = r.room_number
 34	            """;
 35	
 36	    private final DataSource ds;
 37	
 38	    public ReservationService(DataSource ds) {
 39	        this.ds = ds;
 40	    }
 41	
 42	    private <T> T tx(Work<T> work) {
 43	        try (Connection c = ds.getConnection()) {
 44	            c.setAutoCommit(false);
 45	            try {
 46	                T result = work.run(c);
 47	                c.commit();
 48	                return result;
 49	            } catch (Throwable t) {
 50	                c.rollback();
 51	                throw t;
 52	            }
 53	        } catch (SQLException e) {
 54	            throw new IllegalStateException(e);
 55	        }
 56	    }
 57	
 58	    // ---------- consultas ----------
 59	
 60	    public List<Room> rooms() {
 61	        return tx(c -> {
 62	            List<Room> list = new ArrayList<>();
 63	            try (Statement st = c.createStatement();
 64	                 ResultSet rs = st.executeQuery("SELECT * FROM rooms ORDER BY number")) {
 65	                while (rs.next()) list.add(room(rs));
 66	            }
 67	            return list;
 68	        });
 69	    }
 70	
 71	    public List<Message> messages() {
 72	        return tx(c -> {
 73	            List<Message> list = new ArrayList<>();
 74	            try (Statement st = c.createStatement();
 75	                 ResultSet rs = st.executeQuery("SELECT * FROM messages ORDER BY id")) {
 76	                while (rs.next()) {
 77	                    list.add(new Message(rs.getLong("id"), rs.getString("channel"), rs.getString("recipient"),
 78	                            rs.getString("subject"), rs.getString("body")));
 79	                }
 80	            }
 81	            return list;
 82	        });
 83	    }
