241	                try (ResultSet rs = ps.executeQuery()) {
242	                    while (rs.next()) {
243	                        Reservation r = reservation(rs);
244	                        BigDecimal kept = r.amountPaid().subtract(r.refund() == null ? BigDecimal.ZERO : r.refund());
245	                        sum = sum.add(kept);
246	                        sb.append(r.id()).append(',').append(r.roomNumber()).append(',').append(r.checkIn()).append(',')
247	                          .append(r.checkOut()).append(',').append(r.status()).append(',').append(Money.plain(kept)).append('\n');
248	                    }
249	                }
250	            }
251	            return sb.append("total,").append(Money.plain(sum)).append('\n').toString();
252	        });
253	    }
254	
255	    // ---------- internos ----------
256	
257	    private static void requireStatus(Reservation r, String action, String... allowed) {
258	        for (String s : allowed) if (r.status().equals(s)) return;
259	        throw ApiException.notAllowed("Não é possível " + action + " uma reserva com status " + r.status());
260	    }
261	
262	    private static void update(Connection c, String sql, long id) throws SQLException {
263	        try (PreparedStatement ps = c.prepareStatement(sql)) {
264	            ps.setLong(1, id);
265	            ps.executeUpdate();
266	        }
267	    }
268	
269	    private static Reservation load(Connection c, long id, boolean lock) throws SQLException {
270	        try (PreparedStatement ps = c.prepareStatement(
271	                SELECT_RESERVATION + "WHERE r.id = ?" + (lock ? " FOR UPDATE OF r" : ""))) {
272	            ps.setLong(1, id);
273	            try (ResultSet rs = ps.executeQuery()) {
274	                if (!rs.next()) throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe");
275	                return reservation(rs);
276	            }
277	        }
278	    }
279	
280	    private static Room room(ResultSet rs) throws SQLException {
281	        return new Room(rs.getInt("number"), RoomType.valueOf(rs.getString("type")), rs.getInt("capacity"),
282	                rs.getBigDecimal("nightly_rate"));
283	    }
284	
285	    private static Reservation reservation(ResultSet rs) throws SQLException {
286	        return new Reservation(rs.getLong("id"), rs.getInt("room_number"), RoomType.valueOf(rs.getString("room_type")),
287	                rs.getString("guest_name"), rs.getString("guest_email"), rs.getString("guest_cpf"),
288	                rs.getDate("check_in").toLocalDate(), rs.getDate("check_out").toLocalDate(), rs.getInt("guests"),
289	                rs.getString("rate_plan"), rs.getInt("nights"), rs.getBigDecimal("subtotal"),
290	                rs.getBigDecimal("discount"), rs.getBigDecimal("total"), rs.getString("status"),
291	                rs.getBigDecimal("amount_paid"), rs.getBigDecimal("refund"));
292	    }
293	}
