305	    private Db() {}
306	
307	    /** Abre o pool, esperando o banco ficar disponível (ele pode subir junto com o sistema). */
308	    public static HikariDataSource connect(String url, String user, String password) {
309	        HikariConfig cfg = new HikariConfig();
310	        cfg.setJdbcUrl(url);
311	        cfg.setUsername(user);
312	        cfg.setPassword(password);
313	        cfg.setMaximumPoolSize(10);
314	        cfg.setInitializationFailTimeout(-1);
315	        HikariDataSource ds = new HikariDataSource(cfg);
316	        long deadline = System.currentTimeMillis() + 60_000;
317	        while (true) {
318	            try (Connection c = ds.getConnection()) {
319	                return ds;
320	            } catch (SQLException e) {
321	                if (System.currentTimeMillis() > deadline) throw new IllegalStateException("Banco indisponível", e);
322	                try { Thread.sleep(1000); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); }
323	            }
324	        }
325	    }
