327	    /** Cria o que faltar no banco e garante os cinco quartos. Seguro para rodar a cada subida. */
328	    public static void migrate(DataSource ds) throws SQLException {
329	        try (Connection c = ds.getConnection(); Statement st = c.createStatement()) {
330	            c.setAutoCommit(false);
331	            st.execute("SELECT pg_advisory_xact_lock(7070001)");
