     9	/** Todo valor em dinheiro passa por aqui: centavos, arredondamento "meio para o par". */
    10	public final class Money {
    11	    public static final BigDecimal ZERO = new BigDecimal("0.00");
    12	
    13	    private Money() {}
    14	
    15	    public static BigDecimal round(BigDecimal v) {
    16	        return v.setScale(2, RoundingMode.HALF_EVEN);
    17	    }
    18	
    19	    /** base * fator, arredondado (fator como 0.15 para 15%). */
    20	    public static BigDecimal times(BigDecimal base, BigDecimal factor) {
    21	        return round(base.multiply(factor));
    22	    }
    23	
    24	    /** R$ 1.234,56 */
    25	    public static String brl(BigDecimal v) {
    26	        DecimalFormatSymbols s = new DecimalFormatSymbols(Locale.ROOT);
    27	        s.setDecimalSeparator(',');
    28	        s.setGroupingSeparator('.');
    29	        return "R$ " + new DecimalFormat("#,##0.00", s).format(round(v));
    30	    }
    31	
    32	    /** 1234.56, para JSON e CSV. */
    33	    public static String plain(BigDecimal v) {
