    27	        s.setDecimalSeparator(',');
    28	        s.setGroupingSeparator('.');
    29	        return "R$ " + new DecimalFormat("#,##0.00", s).format(round(v));
    30	    }
    31	
    32	    /** 1234.56, para JSON e CSV. */
