     3	import pousada.Money;
     4	import pousada.Room;
     5	import pousada.Season;
     6	
     7	import java.math.BigDecimal;
     8	import java.time.LocalDate;
     9	import java.time.temporal.ChronoUnit;
    10	
    11	/** Tudo o que um plano de tarifa pode precisar para decidir se aceita a reserva e quanto ela custa. */
    12	public record BookingContext(Room room, LocalDate checkIn, LocalDate checkOut, int guests, String companyCode) {
    13	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
    14	
    15	    public int nights() {
    16	        return (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    17	    }
    18	
    19	    /** Soma das noites ao preço de tabela (com a alta temporada), cada noite arredondada. */
    20	    public BigDecimal seasonalSubtotal() {
    21	        BigDecimal sum = Money.ZERO;
    22	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    23	            BigDecimal night = Season.isHigh(d) ? Money.times(room.nightlyRate(), HIGH_SEASON) : room.nightlyRate();
    24	            sum = sum.add(night);
    25	        }
    26	        return Money.round(sum);
    27	    }
    28	}
