  9	import java.math.BigDecimal;
 10	import java.time.LocalDate;
 11	
 12	import static org.junit.jupiter.api.Assertions.*;
 13	
 14	class PlansTest {
 15	    private static final Room STANDARD = new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90"));
 16	    private static final Room DELUXE = new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90"));
 17	
 18	    private static BookingContext ctx(Room room, String in, String out, String company) {
 19	        return new BookingContext(room, LocalDate.parse(in), LocalDate.parse(out), 2, company);
 20	    }
 21	
 22	    private static Quote quote(String plan, BookingContext c) {
 23	        RatePlan p = RatePlans.get(plan);
 24	        p.validate(c);
 25	        return p.quote(c);
 26	    }
 27	
 28	    private static BigDecimal d(String v) { return new BigDecimal(v); }
 29	
 30	    @Test
 31	    void highSeasonStandard() {
 32	        Quote q = quote("STANDARD", ctx(STANDARD, "2027-07-10", "2027-07-12", null));
 33	        assertEquals(d("599.76"), q.subtotal());
 34	        assertEquals(d("599.76"), q.total());
 35	    }
 36	
 37	    @Test
 38	    void seasonBoundaries() {
 39	        assertFalse(Season.isHigh(LocalDate.parse("2027-12-14")));
 40	        assertTrue(Season.isHigh(LocalDate.parse("2027-12-15")));
 41	        assertTrue(Season.isHigh(LocalDate.parse("2028-02-29")));
 42	        assertFalse(Season.isHigh(LocalDate.parse("2028-03-01")));
 43	        assertFalse(Season.isHigh(LocalDate.parse("2027-06-30")));
 44	        assertTrue(Season.isHigh(LocalDate.parse("2027-07-31")));
 45	        assertFalse(Season.isHigh(LocalDate.parse("2027-08-01")));
 46	    }
 47	
 48	    @Test
 49	    void nonRefundable() {
 50	        Quote q = quote("NON_REFUNDABLE", ctx(DELUXE, "2027-03-10", "2027-03-12", null));
 51	        assertEquals(d("779.80"), q.subtotal());
 52	        assertEquals(d("116.97"), q.discount());
 53	        assertEquals(d("662.83"), q.total());
 54	        assertEquals(d("0.00"), RatePlans.get("NON_REFUNDABLE").refund(d("662.83")));
 55	    }
 56	
 57	    @Test
 58	    void corporateTecnosul() {
 59	        Quote q = quote("CORPORATE", ctx(DELUXE, "2027-03-10", "2027-03-12", "TECNOSUL"));
 60	        assertEquals(d("779.80"), q.subtotal());
 61	        assertEquals(d("93.58"), q.discount());
 62	        assertEquals(d("686.22"), q.total());
 63	        assertEquals(d("686.22"), RatePlans.get("CORPORATE").refund(d("686.22")));
 64	    }
 65	
 66	    @Test
 67	    void corporateRequiresKnownCode() {
 68	        RatePlan p = RatePlans.get("CORPORATE");
 69	        assertThrows(ApiException.class, () -> p.validate(ctx(DELUXE, "2027-03-10", "2027-03-12", null)));
 70	        assertThrows(ApiException.class, () -> p.validate(ctx(DELUXE, "2027-03-10", "2027-03-12", "OUTRA")));
 71	        assertThrows(ApiException.class, () -> p.validate(ctx(DELUXE, "2027-03-10", "2027-03-12", "tecnosul")));
 72	    }
 73	
