182	    private static HttpResponse<String> call(String method, String path, String body) throws Exception {
183	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
184	        if (body == null) b.method(method, HttpRequest.BodyPublishers.noBody());
185	        else b.header("Content-Type", "application/json").method(method, HttpRequest.BodyPublishers.ofString(body));
186	        return HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString());
