144	/** Sobe a API de verdade contra o PostgreSQL (DB_URL), num schema descartável. */
145	class ApiIntegrationTest {
146	    private static final ObjectMapper M = new ObjectMapper()
147	            .enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS);
148	    private static final HttpClient HTTP = HttpClient.newHttpClient();
149	    private static String schema;
150	    private static String url, user, password;
151	    private static HikariDataSource ds;
152	    private static Javalin app;
153	    private static String base;
154	
155	    @BeforeAll
156	    static void start() throws Exception {
157	        url = System.getenv("DB_URL");
158	        user = System.getenv("DB_USER");
159	        password = System.getenv("DB_PASSWORD");
160	        assumeTrue(url != null, "DB_URL não definida: teste de integração ignorado");
161	        schema = "it_" + UUID.randomUUID().toString().replace("-", "");
162	        try (Connection c = DriverManager.getConnection(url, user, password); Statement st = c.createStatement()) {
163	            st.execute("CREATE SCHEMA " + schema);
164	        }
165	        ds = Db.connect(url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema, user, password);
166	        Db.migrate(ds);
167	        app = Api.create(new ReservationService(ds)).start(0);
168	        base = "http://localhost:" + app.port();
169	    }
170	
171	    @AfterAll
172	    static void stop() throws Exception {
173	        if (app != null) app.stop();
174	        if (ds != null) ds.close();
175	        if (schema != null) {
176	            try (Connection c = DriverManager.getConnection(url, user, password); Statement st = c.createStatement()) {
177	                st.execute("DROP SCHEMA " + schema + " CASCADE");
178	            }
179	        }
180	    }
181	
182	    private static HttpResponse<String> call(String method, String path, String body) throws Exception {
183	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(base + path));
184	        if (body == null) b.method(method, HttpRequest.BodyPublishers.noBody());
185	        else b.header("Content-Type", "application/json").method(method, HttpRequest.BodyPublishers.ofString(body));
186	        return HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString());
187	    }
188	
189	    private static JsonNode json(HttpResponse<String> r) throws Exception { return M.readTree(r.body()); }
190	
191	    private static String booking(int room, String in, String out, int guests, String plan, String company) {
192	        return """
193	            {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"carla@example.com","guestCpf":"111.222.333-44",
194	             "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"%s}"""
195	                .formatted(room, in, out, guests, plan, company == null ? "" : ",\"companyCode\":\"" + company + "\"");
196	    }
197	
198	    private static JsonNode create(int room, String in, String out, int guests, String plan, String company) throws Exception {
199	        HttpResponse<String> r = call("POST", "/reservations", booking(room, in, out, guests, plan, company));
200	        assertEquals(201, r.statusCode(), r.body());
201	        return json(r);
202	    }
203	
204	    private static void assertError(HttpResponse<String> r, int status, String code) throws Exception {
205	        assertEquals(status, r.statusCode(), r.body());
206	        assertEquals(code, json(r).get("error").asText());
207	    }
