212	        assertEquals(5, rooms.size());
213	        assertEquals(101, rooms.get(0).get("number").asInt());
214	        assertEquals("SUITE", rooms.get(4).get("type").asText());
215	        assertEquals(579.90, rooms.get(4).get("nightlyRate").asDouble());
