218	    @Test
219	    void fullLifecycleWithReceiptAndEmail() throws Exception {
220	        JsonNode r = create(201, "2031-03-10", "2031-03-12", 2, "STANDARD", null);
221	        long id = r.get("id").asLong();
222	        assertEquals("PENDING", r.get("status").asText());
223	        assertEquals("779.80", r.get("total").decimalValue().setScale(2).toPlainString());
224	        assertEquals("0.00", r.get("amountPaid").decimalValue().setScale(2).toPlainString());
225	        assertTrue(r.get("refund").isNull());
226	
227	        assertError(call("GET", "/reservations/" + id + "/document", null), 409, "OPERATION_NOT_ALLOWED");
228	        assertError(call("POST", "/reservations/" + id + "/check-in", null), 409, "OPERATION_NOT_ALLOWED");
229	
230	        JsonNode c = json(call("POST", "/reservations/" + id + "/confirmation", null));
231	        assertEquals("CONFIRMED", c.get("status").asText());
232	        assertEquals("779.80", c.get("amountPaid").decimalValue().setScale(2).toPlainString());
233	        assertError(call("POST", "/reservations/" + id + "/confirmation", null), 409, "OPERATION_NOT_ALLOWED");
234	
235	        JsonNode msgs = json(call("GET", "/messages", null));
236	        JsonNode m = msgs.get(msgs.size() - 1);
237	        assertEquals("EMAIL", m.get("channel").asText());
238	        assertEquals("carla@example.com", m.get("to").asText());
239	        assertEquals("Reserva confirmada - Pousada Maré Alta", m.get("subject").asText());
240	        String receipt = "Comprovante de reserva nº " + id + "\n"
241	                + "Hóspede: Carla Dias (CPF 111.222.333-44)\n"
242	                + "Quarto: 201 (DELUXE)\n"
243	                + "Entrada: 10/03/2031 | Saída: 12/03/2031 | 2 diárias\n"
244	                + "Diárias: R$ 779,80\n"
245	                + "Total: R$ 779,80";
246	        assertEquals("Olá, Carla Dias!\n\nSua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
247	                + receipt + "\n\nA entrada é a partir das 14h, e a saída, até as 12h.\nAté breve!", m.get("body").asText());
248	
249	        assertEquals("CHECKED_IN", json(call("POST", "/reservations/" + id + "/check-in", null)).get("status").asText());
250	        assertError(call("POST", "/reservations/" + id + "/cancellation", null), 409, "OPERATION_NOT_ALLOWED");
251	        JsonNode doc = json(call("POST", "/reservations/" + id + "/check-out", null));
252	        assertEquals("Comprovante de reserva", doc.get("title").asText());
253	        assertEquals(id, doc.get("reservationId").asLong());
254	        assertEquals("DELUXE", doc.get("roomType").asText());
255	        assertEquals("779.80", doc.get("total").decimalValue().setScale(2).toPlainString());
256	        assertEquals(doc, json(call("GET", "/reservations/" + id + "/document", null)));
257	        assertEquals("CHECKED_OUT", json(call("GET", "/reservations/" + id, null)).get("status").asText());
258	    }
