260	    @Test
261	    void availabilityAndCancellationFreesRoom() throws Exception {
262	        JsonNode a = create(101, "2031-05-10", "2031-05-12", 2, "NON_REFUNDABLE", null);
263	        assertEquals("2031-05-10", a.get("checkIn").asText());
264	        assertError(call("POST", "/reservations", booking(101, "2031-05-11", "2031-05-13", 1, "STANDARD", null)),
265	                409, "ROOM_UNAVAILABLE");
266	        // saída no dia da entrada de outra não conflita
267	        create(101, "2031-05-12", "2031-05-13", 1, "STANDARD", null);
268	        long id = a.get("id").asLong();
269	        call("POST", "/reservations/" + id + "/confirmation", null);
270	        JsonNode cancelled = json(call("POST", "/reservations/" + id + "/cancellation", null));
271	        assertEquals("CANCELLED", cancelled.get("status").asText());
272	        assertEquals("0.00", cancelled.get("refund").decimalValue().setScale(2).toPlainString());
273	        assertEquals("424.83", cancelled.get("amountPaid").decimalValue().setScale(2).toPlainString()); // 499.80 - 15%
274	        create(101, "2031-05-11", "2031-05-12", 1, "STANDARD", null);
275	    }
