285	    @Test
286	    void validationErrors() throws Exception {
287	        assertError(call("POST", "/reservations", "não é json"), 400, "INVALID_REQUEST");
288	        assertError(call("POST", "/reservations", "{}"), 400, "INVALID_REQUEST");
289	        assertError(call("POST", "/reservations", booking(101, "2031-05-10", "2031-05-10", 1, "STANDARD", null)), 400, "INVALID_REQUEST");
290	        assertError(call("POST", "/reservations", booking(101, "2031-05-10", "2031-05-11", 0, "STANDARD", null)), 400, "INVALID_REQUEST");
291	        assertError(call("POST", "/reservations", booking(101, "10/05/2031", "2031-05-11", 1, "STANDARD", null)), 400, "INVALID_REQUEST");
292	        assertError(call("POST", "/reservations", booking(101, "2031-05-10", "2031-05-11", 1, "NOPE", null)), 400, "INVALID_REQUEST");
293	        assertError(call("POST", "/reservations", booking(999, "2031-05-10", "2031-05-11", 1, "STANDARD", null)), 404, "ROOM_NOT_FOUND");
294	        assertError(call("POST", "/reservations", booking(101, "2031-05-10", "2031-05-11", 3, "STANDARD", null)), 422, "CAPACITY_EXCEEDED");
295	        assertError(call("GET", "/reservations/99999", null), 404, "RESERVATION_NOT_FOUND");
296	        assertError(call("GET", "/reservations/abc", null), 404, "RESERVATION_NOT_FOUND");
297	        assertError(call("GET", "/reports/occupancy?date=2031-13-01", null), 400, "INVALID_REQUEST");
298	        assertError(call("GET", "/reports/occupancy", null), 400, "INVALID_REQUEST");
299	        assertError(call("GET", "/reports/revenue?month=2031-7", null), 400, "INVALID_REQUEST");
300	    }
