302	    @Test
303	    void planRules() throws Exception {
304	        assertError(call("POST", "/reservations", booking(201, "2031-03-10", "2031-03-12", 2, "CORPORATE", null)), 400, "INVALID_REQUEST");
305	        assertError(call("POST", "/reservations", booking(201, "2031-03-10", "2031-03-12", 2, "CORPORATE", "XPTO")), 400, "INVALID_REQUEST");
306	        assertError(call("POST", "/reservations", booking(201, "2031-03-10", "2031-03-12", 2, "LONG_STAY", null)), 400, "INVALID_REQUEST");
307	        assertError(call("POST", "/reservations", booking(201, "2031-03-10", "2031-03-12", 2, "WEEKEND_PACKAGE", null)), 400, "INVALID_REQUEST");
308	
309	        JsonNode corp = create(201, "2031-09-10", "2031-09-12", 2, "CORPORATE", "TECNOSUL");
310	        assertEquals("93.58", corp.get("discount").decimalValue().setScale(2).toPlainString());
311	        assertEquals("686.22", corp.get("total").decimalValue().setScale(2).toPlainString());
312	        // companyCode é ignorado fora do convênio
313	        assertEquals("779.80", create(202, "2031-09-10", "2031-09-12", 2, "STANDARD", "XPTO").get("total").decimalValue().setScale(2).toPlainString());
314	
315	        // 2031-03-14 é sexta
316	        JsonNode pkg = create(201, "2031-03-14", "2031-03-16", 2, "WEEKEND_PACKAGE", null);
317	        assertEquals("820.00", pkg.get("subtotal").decimalValue().setScale(2).toPlainString());
318	        assertEquals("0.00", pkg.get("discount").decimalValue().setScale(2).toPlainString());
319	        assertEquals(2, pkg.get("nights").asInt());
320	        long id = pkg.get("id").asLong();
321	        call("POST", "/reservations/" + id + "/confirmation", null);
322	        assertEquals("410.00", json(call("POST", "/reservations/" + id + "/cancellation", null)).get("refund").decimalValue().setScale(2).toPlainString());
323	
324	        JsonNode ls = create(101, "2031-10-01", "2031-10-08", 2, "LONG_STAY", null);
325	        assertEquals("1749.30", ls.get("subtotal").decimalValue().setScale(2).toPlainString());
326	        assertEquals("174.93", ls.get("discount").decimalValue().setScale(2).toPlainString());
327	        assertEquals("1574.37", ls.get("total").decimalValue().setScale(2).toPlainString());
328	    }
