331	    void reports() throws Exception {
332	        long a = create(301, "2032-07-10", "2032-07-12", 4, "STANDARD", null).get("id").asLong();
333	        long b = create(101, "2032-07-11", "2032-07-13", 2, "NON_REFUNDABLE", null).get("id").asLong();
334	        long pending = create(202, "2032-07-10", "2032-07-12", 2, "STANDARD", null).get("id").asLong();
335	        call("POST", "/reservations/" + a + "/confirmation", null);
336	        call("POST", "/reservations/" + b + "/confirmation", null);
337	        call("POST", "/reservations/" + b + "/cancellation", null);
338	
339	        HttpResponse<String> occ = call("GET", "/reports/occupancy?date=2032-07-11", null);
340	        assertEquals("text/csv; charset=utf-8", occ.headers().firstValue("Content-Type").orElse(""));
341	        assertEquals("room,type,reservation,check_in,check_out\n301,SUITE," + a + ",2032-07-10,2032-07-12\ntotal,1/5\n", occ.body());
342	        assertEquals("room,type,reservation,check_in,check_out\ntotal,0/5\n",
343	                call("GET", "/reports/occupancy?date=2032-07-12", null).body());
344	
345	        String rev = call("GET", "/reports/revenue?month=2032-07", null).body();
346	        // a: 2 noites de suíte em julho = 2*695.88 = 1391.76; b: 2*299.88=599.76 -15% = 509.80, pago e não devolvido
347	        assertEquals("reservation,room,check_in,check_out,status,amount\n"
348	                + a + ",301,2032-07-10,2032-07-12,CONFIRMED,1391.76\n"
349	                + b + ",101,2032-07-11,2032-07-13,CANCELLED,509.80\n"
350	                + "total,1901.56\n", rev);
351	        assertFalse(rev.contains(pending + ",202"));
352	    }
